int a = 10;
int b = 3;
System.out.println(a + b);
System.out.println(a - b);
System.out.println(a * b);
System.out.println(a / b);
System.out.println(a % b);

int age = 20;
boolean student = true;
System.out.println(age >= 18 && student);
System.out.println(age < 18 || student);
System.out.println(!student);

int count = 5;
count++;
System.out.println(count);
count--;
System.out.println(count);

int number = 50;
double value = number;
System.out.println(value);

double price = 99.99;
int amount = (int) price;
System.out.println(amount);
